<script setup lang="ts">import { ref, computed } from "vue"import { scv, cx } from "css-variants"import RLVButton from "@rimelight/ui/components/vue/RLVButton.vue"import { useRC, useHeaderStack } from "@/composables"import OrganizationsMenu from "../OrganizationsMenu.vue"import TeamsMenu from "../TeamsMenu.vue"export interface NavigationMenuItem {  label: string  to?: string  icon?: string  active?: boolean}/* region Props */export interface BaseDashboardLayoutProps {  id?: string  sidebarOpen?: boolean  links?: NavigationMenuItem[] | NavigationMenuItem[][]  footerLinks?: NavigationMenuItem[] | NavigationMenuItem[][]  searchGroups?: any[]  headerLayerId?: string  headerOrder?: number  rc?: {    root?: string    dashboardGroup?: string    sidebar?: string    sidebarFooterWrapper?: string    footerActions?: string  }}const {  id = "default",  sidebarOpen = false,  links = [],  footerLinks = [],  searchGroups = [],  headerLayerId = "global-header",  headerOrder = 2,  rc: rcProp} = defineProps<BaseDashboardLayoutProps>()const { rc } = useRC("BaseDashboardLayout", rcProp)/* endregion *//* region Emits */export interface BaseDashboardLayoutEmits {  "update:sidebarOpen": [value: boolean]}const emit = defineEmits<BaseDashboardLayoutEmits>()/* endregion *//* region Slots */export interface BaseDashboardLayoutSlots {  "header": (props: {}) => any  "sidebar-header": (props: { collapsed: boolean }) => any  "sidebar-content": (props: { collapsed: boolean }) => any  "sidebar-footer": (props: { collapsed: boolean }) => any  "sidebar-footer-actions": (props: { collapsed: boolean }) => any  "default": (props: {}) => any  "modals": (props: {}) => any}defineSlots<BaseDashboardLayoutSlots>()/* endregion *//* region Styles */const baseDashboardLayoutStyles = scv({  slots: ["root", "dashboardGroup", "sidebar", "sidebarFooterWrapper", "footerActions"],  base: {    root: "flex h-svh w-full flex-col overflow-hidden",    dashboardGroup: "flex-1 flex min-h-0 overflow-hidden relative",    sidebar:      "h-full border-r border-neutral-200 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-900 transition-all duration-300 flex flex-col justify-between shrink-0 z-30",    sidebarFooterWrapper: "flex flex-col gap-2 w-full",    footerActions: "flex flex-row gap-2 justify-between items-center"  }})const styles = computed(() => {  const resolved = baseDashboardLayoutStyles()  const result: Record<string, string> = {}  for (const [slot, value] of Object.entries(resolved)) {    result[slot] = cx(value, (rc.value as Record<string, string>)[slot])  }  return result})/* endregion *//* region State */const collapsed = ref(false)const sidebarOpenModel = computed({  get: () => sidebarOpen,  set: (val) => emit("update:sidebarOpen", val)})const { totalHeight } = useHeaderStack()const normalizedLinks = computed(() => {  if (!links) return []  const flat = Array.isArray(links[0]) ? (links as any[]).flat() : (links as any[])  return flat})const normalizedFooterLinks = computed(() => {  if (!footerLinks) return []  const flat = Array.isArray(footerLinks[0])    ? (footerLinks as any[]).flat()    : (footerLinks as any[])  return flat})/* endregion */defineOptions({  name: "BaseDashboardLayout"})</script><template>  <div :style="{ '--total-header-offset': `${totalHeight}px` }" :class="styles.root">    <!-- Header Slot -->    <div v-if="$slots.header" class="shrink-0 z-40">      <slot name="header" />    </div>    <div :style="{ paddingTop: 'var(--total-header-offset)' }" :class="styles.dashboardGroup">      <!-- Sidebar -->      <aside        :class="[          styles.sidebar,          sidebarOpenModel ? 'translate-x-0' : '-translate-x-full lg:translate-x-0',          collapsed ? 'w-20' : 'w-64',          'fixed inset-y-0 left-0 lg:static'        ]"      >        <!-- Sidebar Header -->        <div          class="p-4 border-b border-neutral-200/50 dark:border-neutral-800/50 flex flex-col gap-2 shrink-0"        >          <slot name="sidebar-header" :collapsed="collapsed">            <div class="flex flex-col gap-2 w-full">              <OrganizationsMenu :collapsed="collapsed" />              <TeamsMenu :collapsed="collapsed" />            </div>          </slot>        </div>        <!-- Sidebar Content -->        <div class="flex-1 overflow-y-auto p-3 space-y-4">          <slot name="sidebar-content" :collapsed="collapsed">            <nav class="flex flex-col gap-1">              <a                v-for="(item, index) in normalizedLinks"                :key="index"                :href="item.to"                class="flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-medium transition-colors"                :class="[                  item.active                    ? 'bg-primary-500 text-white shadow-md'                    : 'text-neutral-600 hover:bg-neutral-100 dark:text-neutral-300 dark:hover:bg-neutral-850'                ]"              >                <span                  v-if="item.icon"                  :class="[item.icon.replace('lucide:', 'i-lucide-'), 'size-5 shrink-0']"                />                <span v-if="!collapsed" class="truncate">{{ item.label }}</span>              </a>            </nav>          </slot>        </div>        <!-- Sidebar Footer -->        <div          class="p-4 border-t border-neutral-200/50 dark:border-neutral-800/50 flex flex-col gap-2 shrink-0"        >          <slot name="sidebar-footer" :collapsed="collapsed">            <div :class="styles.sidebarFooterWrapper">              <nav v-if="normalizedFooterLinks.length > 0" class="flex flex-col gap-1">                <a                  v-for="(item, index) in normalizedFooterLinks"                  :key="index"                  :href="item.to"                  class="flex items-center gap-3 px-3 py-2 rounded-xl text-sm font-medium transition-colors text-neutral-600 hover:bg-neutral-100 dark:text-neutral-300 dark:hover:bg-neutral-850"                >                  <span                    v-if="item.icon"                    :class="[item.icon.replace('lucide:', 'i-lucide-'), 'size-5 shrink-0']"                  />                  <span v-if="!collapsed" class="truncate">{{ item.label }}</span>                </a>              </nav>              <div class="h-[1px] bg-neutral-200 dark:bg-neutral-800 my-2" />              <div :class="styles.footerActions">                <slot name="sidebar-footer-actions" :collapsed="collapsed" />                <RLVButton                  variant="ghost"                  color="neutral"                  square                  :icon="collapsed ? 'i-lucide-chevron-right' : 'i-lucide-chevron-left'"                  class="rounded-xl ml-auto size-8"                  @click="collapsed = !collapsed"                />              </div>            </div>          </slot>        </div>      </aside>      <!-- Main Content Container -->      <main        class="flex-1 flex flex-col min-w-0 bg-white dark:bg-neutral-950 overflow-hidden relative"      >        <slot />      </main>    </div>    <slot name="modals" />  </div></template>